# Custom dataset wrapper to handle corrupted images
class SafeImageFolder(datasets.ImageFolder):
    def __getitem__(self, index):
        try:
            return super().__getitem__(index)
        except (OSError, IOError, RuntimeError, Exception) as e:
            # If an image is corrupted, skip to the next valid one
            # Try to get a different sample
            new_idx = (index + 1) % len(self.samples)
            return super().__getitem__(new_idx)


